import * as T from './vendor/three.module.min.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {desserts,createDessert,disposeDessert} from './models.js';
import {SoftRenderer} from './soft-renderer.js';
const $=id=>document.getElementById(id),host=$('viewport'),stage=$('stage'),motion=window.matchMedia('(prefers-reduced-motion: reduce)');
let current=desserts[0],model,playing=!motion.matches,opened=false,amount=0,impulse=0,filter='all',renderer,soft=false,last=performance.now(),time=0,lastDraw=0,visible=true,frame=0,modelTime=0;
const scene=new T.Scene();const camera=new T.PerspectiveCamera(36,1,.1,60);camera.position.set(4.6,3.6,6.5);
const canvas=document.createElement('canvas');canvas.tabIndex=0;canvas.setAttribute('role','img');canvas.setAttribute('aria-label','可旋转的立体甜品；方向键旋转，加减键缩放');host.append(canvas);
try{const context=canvas.getContext('webgl2',{alpha:true,antialias:true});if(!context)throw new Error('WebGL unavailable');renderer=new T.WebGLRenderer({canvas,context,alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.28;}
catch{soft=true;canvas.remove();const fallback=document.createElement('canvas');fallback.tabIndex=0;fallback.setAttribute('role','img');fallback.setAttribute('aria-label','可旋转的立体甜品；方向键旋转，加减键缩放');host.append(fallback);renderer=new SoftRenderer(fallback);renderer.setPixelRatio(devicePixelRatio);}
const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.09;controls.enablePan=false;controls.minDistance=4.5;controls.maxDistance=11;controls.minPolarAngle=.3;controls.maxPolarAngle=Math.PI*.49;controls.autoRotate=playing;controls.autoRotateSpeed=.65;controls.target.set(0,1.1,0);controls.update();
const ambient=new T.HemisphereLight('#fff9f0','#d49dad',3.2);scene.add(ambient);const key=new T.DirectionalLight('#fff4e5',4.2);key.position.set(-3,6,5);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-4;key.shadow.camera.right=4;key.shadow.camera.top=4;key.shadow.camera.bottom=-4;key.shadow.bias=-.0007;key.shadow.normalBias=.03;scene.add(key);const fill=new T.DirectionalLight('#c4e6ff',1.6);fill.position.set(4,2,-4);scene.add(fill);const rim=new T.DirectionalLight('#ffe0ed',2.2);rim.position.set(-3,4,-3);scene.add(rim);
if(!soft){const floor=new T.Mesh(new T.PlaneGeometry(100,100),new T.ShadowMaterial({opacity:.13}));floor.rotation.x=-Math.PI/2;floor.position.y=-.11;floor.receiveShadow=true;floor.userData.skipSoft=true;scene.add(floor);
 // A tiny self-contained studio environment gives glass and glaze soft reflections.
 const room=new T.Scene();room.background=new T.Color('#fff7f2');const panel=new T.Mesh(new T.PlaneGeometry(5,4),new T.MeshBasicMaterial({color:'#ffffff',side:T.DoubleSide}));panel.position.set(-3,3,2);panel.lookAt(0,1,0);room.add(panel);const dark=new T.Mesh(new T.PlaneGeometry(4,6),new T.MeshBasicMaterial({color:'#c59cae',side:T.DoubleSide}));dark.position.set(4,2,-2);dark.lookAt(0,1,0);room.add(dark);const pmrem=new T.PMREMGenerator(renderer);const env=pmrem.fromScene(room,.08);scene.environment=env.texture;pmrem.dispose();panel.geometry.dispose();panel.material.dispose();dark.geometry.dispose();dark.material.dispose();}
const persistentActions=new Set(['apple','petal','noir','cottage','slice']);
function choose(id,{scroll=false}={}){const next=desserts.find(e=>e.id===id);if(!next)return;current=next;if(model){scene.remove(model.root);disposeDessert(model.root)}model=createDessert(id,{low:soft});scene.add(model.root);opened=false;amount=0;impulse=0;controls.target.set(0,model.center,0);resetCamera();$('name').textContent=next.name;$('english').textContent=next.english;$('scene-word').textContent=next.word;$('description').textContent=next.description;$('category-label').textContent=next.label;$('counter').textContent=`${String(desserts.indexOf(next)+1).padStart(2,'0')} / 11`;$('scene-caption').textContent=next.caption;$('flavors').replaceChildren(...next.flavors.map(f=>{const s=document.createElement('span');s.textContent=f;return s}));$('action-title').textContent=next.title;$('action-hint').textContent=next.hint;$('action-label').textContent=next.action;$('action').removeAttribute('aria-pressed');if(persistentActions.has(id))$('action').setAttribute('aria-pressed','false');$('feedback').textContent='';stage.style.setProperty('--scene1',next.bg[0]);stage.style.setProperty('--scene2',next.bg[1]);document.documentElement.style.setProperty('--accent',next.accent);renderer.domElement.setAttribute('aria-label',`${next.name}立体模型，拖动或使用方向键旋转`);document.title=`${next.name} · 小甜屿`;renderCards();if(location.hash!==`#${id}`)history.replaceState(null,'',`#${id}`);if(scroll)stage.scrollIntoView({behavior:motion.matches?'instant':'smooth',block:'start'});}
function resetCamera(){const r=host.getBoundingClientRect(),fit=Math.max(1,1.04/(r.width/r.height));controls.target.set(0,model?.center??1.1,0);camera.position.copy(controls.target).add(new T.Vector3(4.6,2.55,6.5).multiplyScalar(Math.min(fit,1.7)));controls.maxDistance=Math.max(11,camera.position.distanceTo(controls.target)*1.2);controls.update();}
function renderCards(){const list=desserts.filter(d=>filter==='all'||d.category===filter);$('collection-count').textContent=`${list.length} 款小小的快乐`;$('cards').replaceChildren(...list.map(d=>{const b=document.createElement('button');b.className='dessert-card';b.setAttribute('aria-pressed',String(current.id===d.id));b.setAttribute('aria-label',`欣赏${d.name}`);const img=document.createElement('img');img.src=`./assets/icons/${d.id}.png`;img.alt='';img.loading='lazy';img.width=320;img.height=280;const info=document.createElement('div');info.className='card-info';const title=document.createElement('div'),name=document.createElement('strong'),number=document.createElement('small'),caption=document.createElement('p');name.textContent=d.name;number.textContent=String(desserts.indexOf(d)+1).padStart(2,'0');caption.textContent=d.label;title.append(name,number);info.append(title,caption);b.append(img,info);b.addEventListener('click',()=>choose(d.id,{scroll:true}));return b}));}
$('action').addEventListener('click',()=>{if(persistentActions.has(current.id)){opened=!opened;$('action-label').textContent=opened?current.undo:current.action;$('action').setAttribute('aria-pressed',String(opened));}impulse=1;$('feedback').textContent=opened||!persistentActions.has(current.id)?current.feedback:'轻轻放好，继续欣赏。';});
function setPlaying(value){playing=value;controls.autoRotate=playing;$('play').textContent=playing?'Ⅱ 暂停旋转':'▷ 继续旋转';$('play').setAttribute('aria-pressed',String(playing))}
$('play').addEventListener('click',()=>setPlaying(!playing));motion.addEventListener('change',()=>setPlaying(!motion.matches));setPlaying(playing);
$('reset').addEventListener('click',()=>{resetCamera();opened=false;amount=0;impulse=0;$('action-label').textContent=current.action;if(persistentActions.has(current.id))$('action').setAttribute('aria-pressed','false');$('feedback').textContent='已重置视角与小互动。';});
function zoom(factor){const delta=camera.position.clone().sub(controls.target),length=T.MathUtils.clamp(delta.length()*factor,controls.minDistance,controls.maxDistance);camera.position.copy(controls.target).add(delta.setLength(length));controls.update()}
$('zoom-in').addEventListener('click',()=>zoom(.88));$('zoom-out').addEventListener('click',()=>zoom(1.13));
renderer.domElement.addEventListener('keydown',e=>{const valid=['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-'];if(!valid.includes(e.key))return;e.preventDefault();if(['+','=','-'].includes(e.key)){zoom(e.key==='-'?1.12:.89);return;}const spherical=new T.Spherical().setFromVector3(camera.position.clone().sub(controls.target));if(e.key==='ArrowLeft')spherical.theta-=.12;if(e.key==='ArrowRight')spherical.theta+=.12;if(e.key==='ArrowUp')spherical.phi-=.1;if(e.key==='ArrowDown')spherical.phi+=.1;spherical.phi=T.MathUtils.clamp(spherical.phi,controls.minPolarAngle,controls.maxPolarAngle);camera.position.copy(controls.target).add(new T.Vector3().setFromSpherical(spherical));controls.update();});
let expanded=false;function syncFull(){expanded=document.fullscreenElement===stage||stage.classList.contains('expanded');$('fullscreen').setAttribute('aria-label',expanded?'退出全屏':'全屏欣赏');$('fullscreen').title=expanded?'退出全屏':'全屏欣赏';resize()}
$('fullscreen').addEventListener('click',async()=>{if(document.fullscreenElement){await document.exitFullscreen();return;}if(stage.classList.contains('expanded')){stage.classList.remove('expanded');syncFull();return;}try{if(!stage.requestFullscreen)throw new Error('Use expanded view');await stage.requestFullscreen()}catch{stage.classList.add('expanded');syncFull()}});document.addEventListener('fullscreenchange',syncFull);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&stage.classList.contains('expanded')){stage.classList.remove('expanded');syncFull()}});
for(const button of document.querySelectorAll('[data-filter]'))button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});renderCards();});
function step(direction){const list=desserts.filter(d=>filter==='all'||d.category===filter),i=list.findIndex(e=>e.id===current.id);choose(list[(i+direction+list.length)%list.length].id);}
$('previous').addEventListener('click',()=>step(-1));$('next').addEventListener('click',()=>step(1));window.addEventListener('hashchange',()=>choose(location.hash.slice(1)));
function resize(){const r=host.getBoundingClientRect();if(!r.width||!r.height)return;camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height,false)}const observer=new ResizeObserver(resize);observer.observe(host);const intersection=new IntersectionObserver(es=>{visible=es[0].isIntersecting});intersection.observe(stage);
function animate(now){frame=requestAnimationFrame(animate);if(soft&&now-lastDraw<67)return;lastDraw=now;const dt=Math.min((now-last)/1000,.08);last=now;if(document.hidden||!visible)return;time+=dt;const target=opened?1:0;amount=motion.matches?target:amount+(target-amount)*(1-Math.exp(-dt*6));if(Math.abs(target-amount)<.0005)amount=target;impulse=Math.max(0,impulse-dt*.35);if(playing||impulse>0)modelTime+=dt;model.update({time:modelTime,amount,impulse:motion.matches?impulse*.25:impulse});controls.update(dt);renderer.render(scene,camera)}
choose(desserts.some(d=>d.id===location.hash.slice(1))?location.hash.slice(1):'apple');resize();$('loading').remove();frame=requestAnimationFrame(animate);
window.addEventListener('pagehide',e=>{cancelAnimationFrame(frame);if(e.persisted)return;observer.disconnect();intersection.disconnect();controls.dispose();renderer.dispose();disposeDessert(model.root)});
window.addEventListener('pageshow',e=>{if(e.persisted){last=performance.now();frame=requestAnimationFrame(animate)}});
